module student_swap(\n    input clk,\n    input rst_n,\n    input start,\n    input [3:0] arr0, arr1, arr2, arr3, arr4, arr5, arr6, arr7,\n    output reg [15:0] result,\n    output reg done\n);\n\n// State encoding\nlocalparam [2:0] IDLE  = 3'b000;\nlocalparam [2:0] COUNT = 3'b001;\nlocalparam [2:0] CALC1 = 3'b010;\nlocalparam [2:0] CALC2 = 3'b011;\nlocalparam [2:0] DONE  = 3'b100;\n\nreg [2:0] state;\nreg [2:0] index;\nreg [3:0] cnt0, cnt1, cnt2, cnt3, cnt4;\n\nalways @(posedge clk or negedge rst_n) begin\n    if (!rst_n) begin\n        state <= IDLE;\n        done <= 1'b0;\n        result <= 16'd0;\n        index <= 3'd0;\n        cnt0 <= 4'd0; cnt1 <= 4'd0; cnt2 <= 4'd0; cnt3 <= 4'd0; cnt4 <= 4'd0;\n    end else begin\n        case (state)\n            IDLE: begin\n                done <= 1'b0;\n                if (start) begin\n                    index <= 3'd0;\n                    cnt0 <= 4'd0; cnt1 <= 4'd0; cnt2 <= 4'd0; cnt3 <= 4'd0; cnt4 <= 4'd0;\n                    state <= COUNT;\n                end\n            end\n\n            COUNT: begin\n                case (index)\n                    3'd0: case(arr0) 4'd0: cnt0<=cnt0+4'd1; 4'd1: cnt1<=cnt1+4'd1; 4'd2: cnt2<=cnt2+4'd1; 4'd3: cnt3<=cnt3+4'd1; 4'd4: cnt4<=cnt4+4'd1; endcase\n                    3'd1: case(arr1) 4'd0: cnt0<=cnt0+4'd1; 4'd1: cnt1<=cnt1+4'd1; 4'd2: cnt2<=cnt2+4'd1; 4'd3: cnt3<=cnt3+4'd1; 4'd4: cnt4<=cnt4+4'd1; endcase\n                    3'd2: case(arr2) 4'd0: cnt0<=cnt0+4'd1; 4'd1: cnt1<=cnt1+4'd1; 4'd2: cnt2<=cnt2+4'd1; 4'd3: cnt3<=cnt3+4'd1; 4'd4: cnt4<=cnt4+4'd1; endcase\n                    3'd3: case(arr3) 4'd0: cnt0<=cnt0+4'd1; 4'd1: cnt1<=cnt1+4'd1; 4'd2: cnt2<=cnt2+4'd1; 4'd3: cnt3<=cnt3+4'd1; 4'd4: cnt4<=cnt4+4'd1; endcase\n                    3'd4: case(arr4) 4'd0: cnt0<=cnt0+4'd1; 4'd1: cnt1<=cnt1+4'd1; 4'd2: cnt2<=cnt2+4'd1; 4'd3: cnt3<=cnt3+4'd1; 4'd4: cnt4<=cnt4+4'd1; endcase\n                    3'd5: case(arr5) 4'd0: cnt0<=cnt0+4'd1; 4'd1: cnt1<=cnt1+4'd1; 4'd2: cnt2<=cnt2+4'd1; 4'd3: cnt3<=cnt3+4'd1; 4'd4: cnt4<=cnt4+4'd1; endcase\n                    3'd6: case(arr6) 4'd0: cnt0<=cnt0+4'd1; 4'd1: cnt1<=cnt1+4'd1; 4'd2: cnt2<=cnt2+4'd1; 4'd3: cnt3<=cnt3+4'd1; 4'd4: cnt4<=cnt4+4'd1; endcase\n                    3'd7: begin\n                        case(arr7) 4'd0: cnt0<=cnt0+4'd1; 4'd1: cnt1<=cnt1+4'd1; 4'd2: cnt2<=cnt2+4'd1; 4'd3: cnt3<=cnt3+4'd1; 4'd4: cnt4<=cnt4+4'd1; endcase\n                        state <= CALC1;\n                    end\n                endcase\n                if (index != 3'd7) index <= index + 3'd1;\n                else index <= 3'd0;\n            end\n\n            CALC1: begin\n                reg [7:0] total;\n                total = cnt1 + (cnt2<<4'd1) + (cnt3*8'd3) + (cnt4<<4'd2);\n                if ((total < 8'd3) || (total == 8'd5)) begin\n                    result <= 16'hFFFF;\n                    state <= DONE;\n                end else begin\n                    state <= CALC2;\n                end\n            end\n\n            CALC2: begin\n                reg [15:0] ans;\n                reg [3:0] t1, t2, t3, groups, rem;\n                if (cnt1 >= cnt2) begin\n                    ans = cnt2;\n                    t1 = cnt1 - cnt2;\n                    t3 = cnt3 + cnt2;\n                    groups = t1 / 4'd3;\n                    ans = ans + (groups << 16'd1);\n                    t3 = t3 + groups;\n                    rem = t1 % 4'd3;\n                    if (rem == 4'd0) result <= ans;\n                    else if (t3 > 4'd0) result <= ans + rem;\n                    else result <= ans + 16'd2;\n                end else begin\n                    ans = cnt1;\n                    t2 = cnt2 - cnt1;\n                    groups = t2 / 4'd3;\n                    ans = ans + (groups << 16'd1);\n                    rem = t2 % 4'd3;\n                    if (rem == 4'd0) result <= ans;\n                    else if (cnt4 > 4'd0) result <= ans + rem;\n                    else result <= ans + 16'd2;\n                end\n                state <= DONE;\n            end\n\n            DONE: begin\n                done <= 1'b1;\n                state <= IDLE;\n            end\n\n            default: state <= IDLE;\n        endcase\n    end\nend\nendmodule